#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define for_i(i, a, b) for(int i = a; i < b; ++i)

const int MAX = 500;
int modulus, comb[MAX + 1][MAX + 1];
pair<int, int> dpA[MAX + 1], dpB[2][MAX + 1][MAX + 1];

void update(int &x, int y) { if ((x += y) >= modulus) x -= modulus; }

int total_sum(int n) { return n * (n + 1) >> 1; }

int main() {
    int n, m;
    scanf("%d%d%d", &n, &m, &modulus);
    for_i(i, 0, m + 1) {
        comb[i][0] = 1;
        for_i(j, 1, i + 1) {
            update(comb[i][j], comb[i - 1][j]);
            update(comb[i][j], comb[i - 1][j - 1]);
        }
    }
    dpA[0].first = 1;
    for_i(i, 1, m + 1) {
        for_i(j, 1, i + 1) {
            int w = (long long)dpA[j - 1].first * dpA[i - j].first % modulus * comb[i - 1][j - 1] % modulus;
            update(dpA[i].second, (total_sum(j - 1) + total_sum(i - j)) * (long long)w % modulus);
            update(dpA[i].second, (long long)dpA[j - 1].second * dpA[i - j].first % modulus * (i + 1) % modulus * comb[i - 1][j - 1] % modulus);
            update(dpA[i].second, (long long)dpA[j - 1].first * dpA[i - j].second % modulus * (i + 1) % modulus * comb[i - 1][j - 1] % modulus);
            update(dpA[i].first, (long long)w * (i + 1) % modulus);
        }
    }
    dpB[0][0][0].first = 1;
    dpB[1][0][0].first = 1;
    for_i(i, 0, n) {
        for_i(j, 0, i + 1) {
            for_i(ln, 1, n - i + 1) {
                update(dpB[1][i + ln][j].first, dpB[0][i][j].first);
                update(dpB[1][i + ln][j].second, dpB[0][i][j].second);
                update(dpB[0][i + ln][j + ln].first, (long long)dpB[1][i][j].first * dpA[ln].first % modulus * comb[j + ln][j] % modulus);
                update(dpB[0][i + ln][j + ln].second, (long long)dpB[1][i][j].first * dpA[ln].second % modulus * comb[j + ln][j] % modulus);
                update(dpB[0][i + ln][j + ln].second, (long long)dpB[1][i][j].second * dpA[ln].first % modulus * comb[j + ln][j] % modulus);
            }
        }
    }
    int result = dpB[0][n][m].second;
    update(result, dpB[1][n][m].second);
    printf("%d\n", result);
}
